def assign_existing_phones(apps, schema_editor):
    """Give pre-phone rows a unique mobile so the column can become required."""
    user_model = apps.get_model("accounts", "User")
    used: set[str] = set()
    for user in user_model.objects.all().order_by("id"):
        bump = 0
        phone = f"09{user.pk % 1_000_000_000:09d}"
        while phone in used:
            bump += 1
            phone = f"09{(user.pk + bump) % 1_000_000_000:09d}"
        used.add(phone)
        user.phone = phone
        user.username = phone
        user.save(update_fields=["phone", "username"])


